// Mirrors configuration-service configuration_app (WhatsAppConfigurationSerializer).

/** The business's WhatsApp connection. The secrets (access token, App Secret) are never returned. */
export interface WhatsAppConfiguration {
  phone_number_id: string
  /** Callback URL to enter in Meta (WhatsApp → Configuration → Webhook). */
  webhook_url: string
  /** Generated by the backend; entered in Meta next to the Callback URL. */
  verify_token: string
  created_time: string
  last_updated: string
}

/**
 * PUT body. The secrets are required when connecting; when updating, leave them out to keep the
 * saved ones.
 */
export interface WhatsAppConfigurationInput {
  phone_number_id: string
  access_token?: string
  app_secret?: string
}
